486→// ── Send message history to a single browser socket ────────────────────────
487→
488→/** Send full state to a newly connected browser: agent list + message history per agent. */
489→function sendFullStateToSocket(ws: WebSocket) {
490→  if (ws.readyState !== WebSocket.OPEN) return;
491→
492→  // 1. Agent list
493→  ws.send(JSON.stringify({ type: "agent_list", agents: buildAgentList() }));
494→
495→  // 2. Message history per agent
496→  for (const agent of agents.values()) {
497→    if (agent.messageHistory.length > 0) {
498→      ws.send(
499→        JSON.stringify({
500→          type: "message_history",
501→          agentId: agent.agentId,
502→          messages: agent.messageHistory,
503→        })
504→      );
505→    }
506→  }
507→}
