584→// ── tmux cleanup ──────────────────────────────────────────────────────────
585→
586→/** Kill all tmux sessions matching the thos-agent prefix. */
587→function killAllAgentSessions() {
588→  try {
589→    const sessions = execSync("tmux list-sessions -F '#{session_name}'", {
590→      encoding: "utf-8",
591→    })
592→      .trim()
593→      .split("\n")
594→      .filter((s) => s.startsWith(TMUX_SESSION_PREFIX));
595→
596→    for (const s of sessions) {
597→      try {
598→        execSync(`tmux kill-session -t ${s}`, { stdio: "ignore" });
599→        console.log(`[tmux] cleaned up stale session ${s}`);
600→      } catch {}
601→    }
602→  } catch {
603→    // tmux server not running or no sessions — fine
604→  }
605→}
