607→function shutdown() {
608→  console.log("[ws server] shutting down...");
609→
610→  // Persist all agents synchronously before exit
611→  const allPersisted = Array.from(agents.values()).map(toPersistedAgent);
612→  store.flushAll(allPersisted);
613→  console.log(`[ws server] saved ${allPersisted.length} agents to disk`);
614→
615→  killAllAgentSessions();
616→  wss.close();
617→  process.exit(0);
618→}
619→
620→process.on("SIGTERM", shutdown);
621→process.on("SIGINT", shutdown);
622→
623→// Clean up any orphaned tmux sessions from previous runs
624→killAllAgentSessions();
625→
626→console.log(`[ws server] listening on port ${PORT}`);
