571→        if (agent.status !== "error" && agent.status !== "done") {
572→          setAgentStatus(agentId, "disconnected");
573→          // Notify browsers that CLI disconnected
574→          sendToBrowser({ type: "cli_disconnected", agentId });
575→        }
576→      }
577→    });
578→  } else {
579→    console.log(`[ws] unknown path: ${path}, closing`);
580→    ws.close();
581→  }
582→});
583→
584→// ── tmux cleanup ──────────────────────────────────────────────────────────
585→
586→/** Kill all tmux sessions matching the thos-agent prefix. */
587→function killAllAgentSessions() {
588→  try {
589→    const sessions = execSync("tmux list-sessions -F '#{session_name}'", {
590→      encoding: "utf-8",
591→    })
592→      .trim()
593→      .split("\n")
594→      .filter((s) => s.startsWith(TMUX_SESSION_PREFIX));
595→
