Here are all the WebSocket objects straight from the types in `lib/types.ts`, plus the wire-format objects constructed in `server/ws.ts` and `hooks/use-websocket.ts`:

---

## CLI → Server (NDJSON over `/claude/<agentId>`)

```ts
// lib/types.ts:92-96
interface ClaudeSystemHook {
  type: "system";
  subtype: "hook_started" | "hook_response";
  session_id?: string;
}

// lib/types.ts:18-26
interface ClaudeSystemInit {
  type: "system";
  subtype: "init";
  session_id: string;
  tools: unknown[];
  mcp_servers: unknown[];
  model: string;
  cwd: string;
}

// lib/types.ts:33-43
interface ClaudeAssistant {
  type: "assistant";
  message: {
    id: string;
    role: "assistant";
    content: AssistantContentBlock[];
    model: string;
    stop_reason: string | null;
  };
  session_id: string;
}

// lib/types.ts:46-49
type AssistantContentBlock =
  | { type: "text"; text: string }
  | { type: "tool_use"; id: string; name: string; input: Record<string, unknown> }
  | { type: "tool_result"; tool_use_id: string; content: string };

// lib/types.ts:55-66
interface ClaudeResult {
  type: "result";
  subtype: "success" | "error";
  result?: string;
  error?: string;
  session_id: string;
  cost_usd: number;
  duration_ms: number;
  duration_api_ms: number;
  is_error: boolean;
  num_turns: number;
}

// lib/types.ts:75-86
interface ClaudeControlRequest {
  type: "control_request";
  request_id: string;
  request: {
    subtype: "can_use_tool";
    tool_name: string;
    input: Record<string, unknown>;
    tool_use_id?: string;
    description?: string;
  };
  session_id?: string;
}

// (silently ignored — no type defined, just filtered at server/ws.ts:356)
{ type: "keep_alive" }
```

---

## Browser → Server (JSON over `/browser`)

```ts
// lib/types.ts:110-113
interface BrowserSpawn {
  type: "spawn";
  prompt: string;
}

// lib/types.ts:116-120
interface BrowserSendMessage {
  type: "send_message";
  agentId: string;
  content: string;
}

// lib/types.ts:123-128
interface BrowserControlResponse {
  type: "control_response";
  agentId: string;
  request_id: string;
  allow: boolean;
}

// Extended variant with answers (sent by respondToUserQuestion at hooks/use-websocket.ts:463-469)
// Not in the union type but handled at server/ws.ts:464
{
  type: "control_response";
  agentId: string;
  request_id: string;
  allow: true;
  answers: Record<string, string>;  // e.g. { "0": "Option A" }
}
```

---

## Server → Browser (JSON over `/browser`)

```ts
// lib/types.ts:170-173
interface ServerSpawned {
  type: "spawned";
  agentId: string;
}

// lib/types.ts:164-167
interface ServerAgentList {
  type: "agent_list";
  agents: AgentInfo[];
}

// lib/types.ts:155-161
interface AgentInfo {
  agentId: string;
  status: AgentStatus;
  tmuxSession: string | null;
  label: string;
  createdAt: number;
}

// lib/types.ts:141-145
interface ServerStatus {
  type: "status";
  agentId: string;
  status: AgentStatus;
}

// lib/types.ts:134-138
interface ServerRelay {
  type: "relay";
  agentId: string;
  message: ClaudeMessage;   // any of the CLI→Server types above
}

// lib/types.ts:148-152
interface ServerError {
  type: "error";
  agentId: string;
  error: string;
}

// lib/types.ts:176-180
interface ServerMessageHistory {
  type: "message_history";
