  52→  state: SessionState;
  53→  pendingPermissions: Map<string, PermissionRequest>;
  54→  messageHistory: BrowserIncomingMessage[];
  55→  /** Messages queued while waiting for CLI to connect */
  56→  pendingMessages: string[];
  57→}
  58→
  59→type GitSessionKey = "git_branch" | "is_worktree" | "repo_root" | "git_ahead" | "git_behind";
  60→
  61→function makeDefaultState(sessionId: string, backendType: BackendType = "claude"): SessionState {
  62→  return {
  63→    session_id: sessionId,
  64→    backend_type: backendType,
  65→    model: "",
  66→    cwd: "",
  67→    tools: [],
  68→    permissionMode: "default",
  69→    claude_code_version: "",
  70→    mcp_servers: [],
  71→    agents: [],
  72→    slash_commands: [],
  73→    skills: [],
  74→    total_cost_usd: 0,
  75→    num_turns: 0,
  76→    context_used_percent: 0,
  77→    is_compacting: false,
  78→    git_branch: "",
  79→    is_worktree: false,
  80→    repo_root: "",
  81→    git_ahead: 0,
  82→    git_behind: 0,
  83→    total_lines_added: 0,
  84→    total_lines_removed: 0,
  85→  };
  86→}
  87→
  88→// ─── Git info helper ─────────────────────────────────────────────────────────
  89→
  90→function resolveGitInfo(state: SessionState): void {
  91→  if (!state.cwd) return;
  92→  try {
  93→    state.git_branch = execSync("git rev-parse --abbrev-ref HEAD", {
  94→      cwd: state.cwd, encoding: "utf-8", timeout: 3000,
  95→    }).trim();
  96→
  97→    try {
  98→      const gitDir = execSync("git rev-parse --git-dir", {
  99→        cwd: state.cwd, encoding: "utf-8", timeout: 3000,
 100→      }).trim();
 101→      state.is_worktree = gitDir.includes("/worktrees/");
 102→    } catch { /* ignore */ }
 103→
 104→    try {
 105→      if (state.is_worktree) {
 106→        // For worktrees, --show-toplevel returns the worktree dir, not the original repo.
 107→        // Use --git-common-dir to find the shared .git dir, then derive the repo root.
 108→        const commonDir = execSync("git rev-parse --git-common-dir", {
 109→          cwd: state.cwd, encoding: "utf-8", timeout: 3000,
 110→        }).trim();
 111→        state.repo_root = resolve(state.cwd, commonDir, "..");
 112→      } else {
 113→        state.repo_root = execSync("git rev-parse --show-toplevel", {
 114→          cwd: state.cwd, encoding: "utf-8", timeout: 3000,
 115→        }).trim();
 116→      }
 117→    } catch { /* ignore */ }
 118→
 119→    try {
 120→      const counts = execSync(
 121→        "git rev-list --left-right --count @{upstream}...HEAD",
 122→        { cwd: state.cwd, encoding: "utf-8", timeout: 3000 },
 123→      ).trim();
 124→      const [behind, ahead] = counts.split(/\s+/).map(Number);
 125→      state.git_ahead = ahead || 0;
 126→      state.git_behind = behind || 0;
 127→    } catch {
 128→      state.git_ahead = 0;
 129→      state.git_behind = 0;
 130→    }
 131→  } catch {
 132→    // Not a git repo or git not available
 133→    state.git_branch = "";
 134→    state.is_worktree = false;
 135→    state.repo_root = "";
 136→    state.git_ahead = 0;
 137→    state.git_behind = 0;
 138→  }
 139→}
 140→
 141→// ─── Bridge ───────────────────────────────────────────────────────────────────
 142→
 143→export class WsBridge {
 144→  private sessions = new Map<string, Session>();
 145→  private store: SessionStore | null = null;
 146→  private onCLISessionId: ((sessionId: string, cliSessionId: string) => void) | null = null;
 147→  private onCLIRelaunchNeeded: ((sessionId: string) => void) | null = null;
 148→  private onFirstTurnCompleted: ((sessionId: string, firstUserMessage: string) => void) | null = null;
 149→  private autoNamingAttempted = new Set<string>();
 150→  private userMsgCounter = 0;
 151→  private onGitInfoReady: ((sessionId: string, cwd: string, branch: string) => void) | null = null;
 152→  private static readonly GIT_SESSION_KEYS: GitSessionKey[] = [
 153→    "git_branch",
 154→    "is_worktree",
 155→    "repo_root",
 156→    "git_ahead",
 157→    "git_behind",
 158→  ];
 159→
 160→  /** Register a callback for when we learn the CLI's internal session ID. */
 161→  onCLISessionIdReceived(cb: (sessionId: string, cliSessionId: string) => void): void {
 162→    this.onCLISessionId = cb;
 163→  }
 164→
 165→  /** Register a callback for when a browser connects but CLI is dead. */
 166→  onCLIRelaunchNeededCallback(cb: (sessionId: string) => void): void {
 167→    this.onCLIRelaunchNeeded = cb;
 168→  }
 169→
 170→  /** Register a callback for when a session completes its first turn. */
 171→  onFirstTurnCompletedCallback(cb: (sessionId: string, firstUserMessage: string) => void): void {
 172→    this.onFirstTurnCompleted = cb;
 173→  }
 174→
 175→  /** Register a callback for when git info is resolved and branch is known. */
 176→  onSessionGitInfoReadyCallback(cb: (sessionId: string, cwd: string, branch: string) => void): void {
 177→    this.onGitInfoReady = cb;
 178→  }
 179→
 180→  /** Push a message to all connected browsers for a session (public, for PRPoller etc.). */
 181→  broadcastToSession(sessionId: string, msg: BrowserIncomingMessage): void {
 182→    const session = this.sessions.get(sessionId);
 183→    if (!session) return;
 184→    this.broadcastToBrowsers(session, msg);
 185→  }
 186→
 187→  /** Attach a persistent store. Call restoreFromDisk() after. */
 188→  setStore(store: SessionStore): void {
 189→    this.store = store;
 190→  }
 191→
 192→  /** Restore sessions from disk (call once at startup). */
 193→  restoreFromDisk(): number {
 194→    if (!this.store) return 0;
 195→    const persisted = this.store.loadAll();
 196→    let count = 0;
 197→    for (const p of persisted) {
 198→      if (this.sessions.has(p.id)) continue; // don't overwrite live sessions
 199→      const session: Session = {
 200→        id: p.id,
 201→        backendType: p.state.backend_type || "claude",
 202→        cliSocket: null,
 203→        codexAdapter: null,
 204→        browserSockets: new Set(),
 205→        state: p.state,
 206→        pendingPermissions: new Map(p.pendingPermissions || []),
 207→        messageHistory: p.messageHistory || [],
 208→        pendingMessages: p.pendingMessages || [],
 209→      };
 210→      session.state.backend_type = session.backendType;
 211→      // Resolve git info for restored sessions (may have been persisted without it)
 212→      resolveGitInfo(session.state);
 213→      this.sessions.set(p.id, session);
 214→      // Restored sessions with completed turns don't need auto-naming re-triggered
 215→      if (session.state.num_turns > 0) {
 216→        this.autoNamingAttempted.add(session.id);
 217→      }
 218→      count++;
 219→    }
 220→    if (count > 0) {
 221→      console.log(`[ws-bridge] Restored ${count} session(s) from disk`);
 222→    }
 223→    return count;
 224→  }
 225→
 226→  /** Persist a session to disk (debounced). */
 227→  private persistSession(session: Session): void {
 228→    if (!this.store) return;
 229→    this.store.save({
 230→      id: session.id,
 231→      state: session.state,
 232→      messageHistory: session.messageHistory,
 233→      pendingMessages: session.pendingMessages,
 234→      pendingPermissions: Array.from(session.pendingPermissions.entries()),
 235→    });
 236→  }
 237→
 238→  private refreshGitInfo(
 239→    session: Session,
 240→    options: { broadcastUpdate?: boolean; notifyPoller?: boolean } = {},
 241→  ): void {
 242→    const before = {
 243→      git_branch: session.state.git_branch,
 244→      is_worktree: session.state.is_worktree,
 245→      repo_root: session.state.repo_root,
 246→      git_ahead: session.state.git_ahead,
 247→      git_behind: session.state.git_behind,
 248→    };
 249→
 250→    resolveGitInfo(session.state);
 251→
 252→    let changed = false;
 253→    for (const key of WsBridge.GIT_SESSION_KEYS) {
 254→      if (session.state[key] !== before[key]) {
 255→        changed = true;
 256→        break;
 257→      }
 258→    }
 259→
 260→    if (changed) {
 261→      if (options.broadcastUpdate) {
 262→        this.broadcastToBrowsers(session, {
 263→          type: "session_update",
 264→          session: {
 265→            git_branch: session.state.git_branch,
 266→            is_worktree: session.state.is_worktree,
 267→            repo_root: session.state.repo_root,
 268→            git_ahead: session.state.git_ahead,
 269→            git_behind: session.state.git_behind,
 270→          },
 271→        });
 272→      }
 273→      this.persistSession(session);
 274→    }
 275→
 276→    if (options.notifyPoller && session.state.git_branch && session.state.cwd && this.onGitInfoReady) {
 277→      this.onGitInfoReady(session.id, session.state.cwd, session.state.git_branch);
 278→    }
 279→  }
 280→
 281→  // ── Session management ──────────────────────────────────────────────────
 282→
 283→  getOrCreateSession(sessionId: string, backendType?: BackendType): Session {
 284→    let session = this.sessions.get(sessionId);
 285→    if (!session) {
 286→      const type = backendType || "claude";
 287→      session = {
 288→        id: sessionId,
 289→        backendType: type,
 290→        cliSocket: null,
 291→        codexAdapter: null,
 292→        browserSockets: new Set(),
 293→        state: makeDefaultState(sessionId, type),
 294→        pendingPermissions: new Map(),
 295→        messageHistory: [],
 296→        pendingMessages: [],
 297→      };
 298→      this.sessions.set(sessionId, session);
 299→    } else if (backendType) {
 300→      // Only overwrite backendType when explicitly provided (e.g. attachCodexAdapter)
 301→      // Prevents handleBrowserOpen from resetting codex→claude
 302→      session.backendType = backendType;
 303→      session.state.backend_type = backendType;
 304→    }
 305→    return session;
 306→  }
 307→
 308→  getSession(sessionId: string): Session | undefined {
 309→    return this.sessions.get(sessionId);
 310→  }
 311→
 312→  getAllSessions(): SessionState[] {
 313→    return Array.from(this.sessions.values()).map((s) => s.state);
 314→  }
 315→
 316→  getCodexRateLimits(sessionId: string) {
 317→    const session = this.sessions.get(sessionId);
 318→    return session?.codexAdapter?.getRateLimits() ?? null;
 319→  }
 320→
 321→  isCliConnected(sessionId: string): boolean {
 322→    const session = this.sessions.get(sessionId);
 323→    if (!session) return false;
 324→    if (session.backendType === "codex") {
 325→      return !!session.codexAdapter?.isConnected();
 326→    }
 327→    return !!session.cliSocket;
 328→  }
 329→
 330→  removeSession(sessionId: string) {
 331→    this.sessions.delete(sessionId);
 332→    this.autoNamingAttempted.delete(sessionId);
 333→    this.store?.remove(sessionId);
 334→  }
 335→
 336→  /**
 337→   * Close all sockets (CLI + browsers) for a session and remove it.
 338→   */
 339→  closeSession(sessionId: string) {
 340→    const session = this.sessions.get(sessionId);
 341→    if (!session) return;
 342→
 343→    // Close CLI socket (Claude)
 344→    if (session.cliSocket) {
 345→      try { session.cliSocket.close(); } catch {}
 346→      session.cliSocket = null;
 347→    }
 348→
 349→    // Disconnect Codex adapter
 350→    if (session.codexAdapter) {
 351→      session.codexAdapter.disconnect().catch(() => {});
 352→      session.codexAdapter = null;
 353→    }
 354→
 355→    // Close all browser sockets
 356→    for (const ws of session.browserSockets) {
 357→      try { ws.close(); } catch {}
 358→    }
 359→    session.browserSockets.clear();
 360→
 361→    this.sessions.delete(sessionId);
 362→    this.autoNamingAttempted.delete(sessionId);
 363→    this.store?.remove(sessionId);
 364→  }
 365→
 366→  // ── Codex adapter attachment ────────────────────────────────────────────
 367→
 368→  /**
 369→   * Attach a CodexAdapter to a session. The adapter handles all message
 370→   * translation between the Codex app-server (stdio JSON-RPC) and the
 371→   * browser WebSocket protocol.
 372→   */
 373→  attachCodexAdapter(sessionId: string, adapter: CodexAdapter): void {
 374→    const session = this.getOrCreateSession(sessionId, "codex");
 375→    session.backendType = "codex";
 376→    session.state.backend_type = "codex";
 377→    session.codexAdapter = adapter;
 378→
 379→    // Forward translated messages to browsers
 380→    adapter.onBrowserMessage((msg) => {
 381→      if (msg.type === "session_init") {
 382→        session.state = { ...session.state, ...msg.session, backend_type: "codex" };
 383→        this.refreshGitInfo(session, { notifyPoller: true });
 384→        this.persistSession(session);
 385→      } else if (msg.type === "session_update") {
 386→        session.state = { ...session.state, ...msg.session, backend_type: "codex" };
 387→        this.refreshGitInfo(session, { notifyPoller: true });
 388→        this.persistSession(session);
 389→      } else if (msg.type === "status_change") {
 390→        session.state.is_compacting = msg.status === "compacting";
 391→        this.persistSession(session);
 392→      }
 393→
 394→      // Store assistant/result messages in history for replay
 395→      if (msg.type === "assistant") {
 396→        session.messageHistory.push({ ...msg, timestamp: msg.timestamp || Date.now() });
 397→        this.persistSession(session);
 398→      } else if (msg.type === "result") {
 399→        session.messageHistory.push(msg);
 400→        this.persistSession(session);
 401→      }
 402→
 403→      // Diagnostic: log tool_use assistant messages
 404→      if (msg.type === "assistant") {
 405→        const content = (msg as { message?: { content?: Array<{ type: string }> } }).message?.content;
 406→        const hasToolUse = content?.some((b) => b.type === "tool_use");
 407→        if (hasToolUse) {
 408→          console.log(`[ws-bridge] Broadcasting tool_use assistant to ${session.browserSockets.size} browser(s) for session ${session.id}`);
 409→        }
 410→      }
 411→
 412→      // Handle permission requests
 413→      if (msg.type === "permission_request") {
 414→        session.pendingPermissions.set(msg.request.request_id, msg.request);
 415→        this.persistSession(session);
 416→      }
 417→
 418→      this.broadcastToBrowsers(session, msg);
 419→
 420→      // Trigger auto-naming after the first result
 421→      if (
 422→        msg.type === "result" &&
 423→        !(msg.data as { is_error?: boolean }).is_error &&
 424→        this.onFirstTurnCompleted &&
 425→        !this.autoNamingAttempted.has(session.id)
 426→      ) {
 427→        this.autoNamingAttempted.add(session.id);
 428→        const firstUserMsg = session.messageHistory.find((m) => m.type === "user_message");
 429→        if (firstUserMsg && firstUserMsg.type === "user_message") {
 430→          this.onFirstTurnCompleted(session.id, firstUserMsg.content);
 431→        }
 432→      }
 433→    });
 434→
 435→    // Handle session metadata updates
 436→    adapter.onSessionMeta((meta) => {
 437→      if (meta.cliSessionId && this.onCLISessionId) {
 438→        this.onCLISessionId(session.id, meta.cliSessionId);
 439→      }
 440→      if (meta.model) session.state.model = meta.model;
 441→      if (meta.cwd) session.state.cwd = meta.cwd;
 442→      session.state.backend_type = "codex";
 443→      this.refreshGitInfo(session, { broadcastUpdate: true, notifyPoller: true });
 444→      this.persistSession(session);
 445→    });
 446→
 447→    // Handle disconnect
 448→    adapter.onDisconnect(() => {
 449→      for (const [reqId] of session.pendingPermissions) {
 450→        this.broadcastToBrowsers(session, { type: "permission_cancelled", request_id: reqId });
 451→      }
 452→      session.pendingPermissions.clear();
 453→      session.codexAdapter = null;
 454→      this.persistSession(session);
 455→      console.log(`[ws-bridge] Codex adapter disconnected for session ${sessionId}`);
 456→      this.broadcastToBrowsers(session, { type: "cli_disconnected" });
 457→    });
 458→
 459→    // Flush any messages queued while waiting for the adapter
 460→    if (session.pendingMessages.length > 0) {
 461→      console.log(`[ws-bridge] Flushing ${session.pendingMessages.length} queued message(s) to Codex adapter for session ${sessionId}`);
 462→      const queued = session.pendingMessages.splice(0);
 463→      for (const raw of queued) {
 464→        try {
 465→          const msg = JSON.parse(raw) as BrowserOutgoingMessage;
 466→          adapter.sendBrowserMessage(msg);
 467→        } catch {
 468→          console.warn(`[ws-bridge] Failed to parse queued message for Codex: ${raw.substring(0, 100)}`);
 469→        }
 470→      }
 471→    }
 472→
 473→    // Notify browsers that the backend is connected
 474→    this.broadcastToBrowsers(session, { type: "cli_connected" });
 475→    console.log(`[ws-bridge] Codex adapter attached for session ${sessionId}`);
 476→  }
 477→
 478→  // ── CLI WebSocket handlers ──────────────────────────────────────────────
 479→
 480→  handleCLIOpen(ws: ServerWebSocket<SocketData>, sessionId: string) {
 481→    const session = this.getOrCreateSession(sessionId);
 482→    session.cliSocket = ws;
 483→    console.log(`[ws-bridge] CLI connected for session ${sessionId}`);
 484→    this.broadcastToBrowsers(session, { type: "cli_connected" });
 485→
 486→    // Flush any messages that were queued while waiting for CLI to connect
 487→    if (session.pendingMessages.length > 0) {
 488→      console.log(`[ws-bridge] Flushing ${session.pendingMessages.length} queued message(s) for session ${sessionId}`);
 489→      for (const ndjson of session.pendingMessages) {
 490→        this.sendToCLI(session, ndjson);
 491→      }
 492→      session.pendingMessages = [];
 493→    }
 494→  }
 495→
 496→  handleCLIMessage(ws: ServerWebSocket<SocketData>, raw: string | Buffer) {
 497→    const data = typeof raw === "string" ? raw : raw.toString("utf-8");
 498→    const sessionId = (ws.data as CLISocketData).sessionId;
 499→    const session = this.sessions.get(sessionId);
 500→    if (!session) return;
 501→
 502→    // NDJSON: split on newlines, parse each line
 503→    const lines = data.split("\n").filter((l) => l.trim());
 504→    for (const line of lines) {
 505→      let msg: CLIMessage;
 506→      try {
 507→        msg = JSON.parse(line);
 508→      } catch {
 509→        console.warn(`[ws-bridge] Failed to parse CLI message: ${line.substring(0, 200)}`);
 510→        continue;
 511→      }
 512→      this.routeCLIMessage(session, msg);
 513→    }
 514→  }
 515→
 516→  handleCLIClose(ws: ServerWebSocket<SocketData>) {
 517→    const sessionId = (ws.data as CLISocketData).sessionId;
 518→    const session = this.sessions.get(sessionId);
 519→    if (!session) return;
 520→
 521→    session.cliSocket = null;
 522→    console.log(`[ws-bridge] CLI disconnected for session ${sessionId}`);
 523→    this.broadcastToBrowsers(session, { type: "cli_disconnected" });
 524→
 525→    // Cancel any pending permission requests
 526→    for (const [reqId] of session.pendingPermissions) {
 527→      this.broadcastToBrowsers(session, { type: "permission_cancelled", request_id: reqId });
 528→    }
 529→    session.pendingPermissions.clear();
 530→  }
 531→
 532→  // ── Browser WebSocket handlers ──────────────────────────────────────────
 533→
 534→  handleBrowserOpen(ws: ServerWebSocket<SocketData>, sessionId: string) {
 535→    const session = this.getOrCreateSession(sessionId);
 536→    session.browserSockets.add(ws);
 537→    console.log(`[ws-bridge] Browser connected for session ${sessionId} (${session.browserSockets.size} browsers)`);
 538→
 539→    // Refresh git state on browser connect so branch changes made mid-session are reflected.
 540→    this.refreshGitInfo(session, { notifyPoller: true });
 541→
 542→    // Send current session state as snapshot
 543→    const snapshot: BrowserIncomingMessage = {
 544→      type: "session_init",
 545→      session: session.state,
 546→    };
 547→    this.sendToBrowser(ws, snapshot);
 548→
 549→    // Replay message history so the browser can reconstruct the conversation
 550→    if (session.messageHistory.length > 0) {
 551→      this.sendToBrowser(ws, {
 552→        type: "message_history",
 553→        messages: session.messageHistory,
 554→      });
 555→    }
 556→
 557→    // Send any pending permission requests
 558→    for (const perm of session.pendingPermissions.values()) {
 559→      this.sendToBrowser(ws, { type: "permission_request", request: perm });
 560→    }
 561→
 562→    // Notify if backend is not connected and request relaunch
 563→    const backendConnected = session.backendType === "codex"
 564→      // Treat an attached adapter as "alive" during init.
 565→      // `isConnected()` flips true only after initialize/thread start, and
 566→      // relaunching during that window can kill a healthy startup.
 567→      ? !!session.codexAdapter
 568→      : !!session.cliSocket;
 569→
 570→    if (!backendConnected) {
 571→      this.sendToBrowser(ws, { type: "cli_disconnected" });
 572→      if (this.onCLIRelaunchNeeded) {
 573→        console.log(`[ws-bridge] Browser connected but backend is dead for session ${sessionId}, requesting relaunch`);
 574→        this.onCLIRelaunchNeeded(sessionId);
 575→      }
 576→    }
 577→  }
 578→
 579→  handleBrowserMessage(ws: ServerWebSocket<SocketData>, raw: string | Buffer) {
 580→    const data = typeof raw === "string" ? raw : raw.toString("utf-8");
 581→    const sessionId = (ws.data as BrowserSocketData).sessionId;
 582→    const session = this.sessions.get(sessionId);
 583→    if (!session) return;
 584→
 585→    let msg: BrowserOutgoingMessage;
 586→    try {
 587→      msg = JSON.parse(data);
 588→    } catch {
 589→      console.warn(`[ws-bridge] Failed to parse browser message: ${data.substring(0, 200)}`);
 590→      return;
 591→    }
 592→
 593→    this.routeBrowserMessage(session, msg);
 594→  }
 595→
 596→  handleBrowserClose(ws: ServerWebSocket<SocketData>) {
 597→    const sessionId = (ws.data as BrowserSocketData).sessionId;
 598→    const session = this.sessions.get(sessionId);
 599→    if (!session) return;
 600→
 601→    session.browserSockets.delete(ws);
 602→    console.log(`[ws-bridge] Browser disconnected for session ${sessionId} (${session.browserSockets.size} browsers)`);
 603→  }
 604→
 605→  // ── CLI message routing ─────────────────────────────────────────────────
 606→
 607→  private routeCLIMessage(session: Session, msg: CLIMessage) {
 608→    switch (msg.type) {
 609→      case "system":
 610→        this.handleSystemMessage(session, msg);
 611→        break;
 612→
 613→      case "assistant":
 614→        this.handleAssistantMessage(session, msg);
 615→        break;
 616→
 617→      case "result":
 618→        this.handleResultMessage(session, msg);
 619→        break;
 620→
 621→      case "stream_event":
 622→        this.handleStreamEvent(session, msg);
 623→        break;
 624→
 625→      case "control_request":
 626→        this.handleControlRequest(session, msg);
 627→        break;
 628→
 629→      case "tool_progress":
 630→        this.handleToolProgress(session, msg);
 631→        break;
 632→
 633→      case "tool_use_summary":
 634→        this.handleToolUseSummary(session, msg);
 635→        break;
 636→
 637→      case "auth_status":
 638→        this.handleAuthStatus(session, msg);
 639→        break;
 640→
 641→      case "keep_alive":
 642→        // Silently consume keepalives
 643→        break;
 644→
 645→      default:
 646→        // Forward unknown messages as-is for debugging
 647→        break;
 648→    }
 649→  }
 650→
 651→  private handleSystemMessage(session: Session, msg: CLISystemInitMessage | CLISystemStatusMessage) {
 652→    if (msg.subtype === "init") {
 653→      // Keep the launcher-assigned session_id as the canonical ID.
 654→      // The CLI may report its own internal session_id which differs
 655→      // from the launcher UUID, causing duplicate entries in the sidebar.
 656→
 657→      // Store the CLI's internal session_id so we can --resume on relaunch
 658→      if (msg.session_id && this.onCLISessionId) {
 659→        this.onCLISessionId(session.id, msg.session_id);
 660→      }
 661→
 662→      session.state.model = msg.model;
 663→      session.state.cwd = msg.cwd;
 664→      session.state.tools = msg.tools;
 665→      session.state.permissionMode = msg.permissionMode;
 666→      session.state.claude_code_version = msg.claude_code_version;
 667→      session.state.mcp_servers = msg.mcp_servers;
 668→      session.state.agents = msg.agents ?? [];
 669→      session.state.slash_commands = msg.slash_commands ?? [];
 670→      session.state.skills = msg.skills ?? [];
 671→
 672→      // Resolve and publish git info
 673→      this.refreshGitInfo(session, { notifyPoller: true });
 674→
 675→      this.broadcastToBrowsers(session, {
 676→        type: "session_init",
 677→        session: session.state,
 678→      });
 679→      this.persistSession(session);
 680→    } else if (msg.subtype === "status") {
 681→      session.state.is_compacting = msg.status === "compacting";
 682→
 683→      if (msg.permissionMode) {
 684→        session.state.permissionMode = msg.permissionMode;
 685→      }
 686→
 687→      this.broadcastToBrowsers(session, {
 688→        type: "status_change",
 689→        status: msg.status ?? null,
 690→      });
 691→    }
 692→    // Other system subtypes (compact_boundary, task_notification, etc.) can be forwarded as needed
 693→  }
 694→
 695→  private handleAssistantMessage(session: Session, msg: CLIAssistantMessage) {
 696→    const browserMsg: BrowserIncomingMessage = {
 697→      type: "assistant",
 698→      message: msg.message,
 699→      parent_tool_use_id: msg.parent_tool_use_id,
 700→      timestamp: Date.now(),
 701→    };
 702→    session.messageHistory.push(browserMsg);
 703→    this.broadcastToBrowsers(session, browserMsg);
 704→    this.persistSession(session);
 705→  }
 706→
 707→  private handleResultMessage(session: Session, msg: CLIResultMessage) {
 708→    // Update session cost/turns
 709→    session.state.total_cost_usd = msg.total_cost_usd;
 710→    session.state.num_turns = msg.num_turns;
 711→
 712→    // Update lines changed (CLI may send these in result)
 713→    if (typeof msg.total_lines_added === "number") {
 714→      session.state.total_lines_added = msg.total_lines_added;
 715→    }
 716→    if (typeof msg.total_lines_removed === "number") {
 717→      session.state.total_lines_removed = msg.total_lines_removed;
 718→    }
 719→
 720→    // Compute context usage from modelUsage
 721→    if (msg.modelUsage) {
 722→      for (const usage of Object.values(msg.modelUsage)) {
 723→        if (usage.contextWindow > 0) {
 724→          const pct = Math.round(
 725→            ((usage.inputTokens + usage.outputTokens) / usage.contextWindow) * 100
 726→          );
 727→          session.state.context_used_percent = Math.max(0, Math.min(pct, 100));
 728→        }
 729→      }
 730→    }
 731→
 732→    // Re-check git state after each turn in case branch moved during the session.
 733→    this.refreshGitInfo(session, { broadcastUpdate: true, notifyPoller: true });
 734→
 735→    const browserMsg: BrowserIncomingMessage = {
 736→      type: "result",
 737→      data: msg,
 738→    };
 739→    session.messageHistory.push(browserMsg);
 740→    this.broadcastToBrowsers(session, browserMsg);
 741→    this.persistSession(session);
 742→
 743→    // Trigger auto-naming after the first successful result for this session.
 744→    // Note: num_turns counts all internal tool-use turns, so it's typically > 1
 745→    // even on the first user interaction. We track per-session instead.
 746→    if (
 747→      !msg.is_error &&
 748→      this.onFirstTurnCompleted &&
 749→      !this.autoNamingAttempted.has(session.id)
 750→    ) {
 751→      this.autoNamingAttempted.add(session.id);
 752→      const firstUserMsg = session.messageHistory.find(
 753→        (m) => m.type === "user_message",
 754→      );
 755→      if (firstUserMsg && firstUserMsg.type === "user_message") {
 756→        this.onFirstTurnCompleted(session.id, firstUserMsg.content);
 757→      }
 758→    }
 759→  }
 760→
 761→  private handleStreamEvent(session: Session, msg: CLIStreamEventMessage) {
 762→    this.broadcastToBrowsers(session, {
 763→      type: "stream_event",
 764→      event: msg.event,
 765→      parent_tool_use_id: msg.parent_tool_use_id,
 766→    });
 767→  }
