 769→  private handleControlRequest(session: Session, msg: CLIControlRequestMessage) {
 770→    if (msg.request.subtype === "can_use_tool") {
 771→      const perm: PermissionRequest = {
 772→        request_id: msg.request_id,
 773→        tool_name: msg.request.tool_name,
 774→        input: msg.request.input,
 775→        permission_suggestions: msg.request.permission_suggestions,
 776→        description: msg.request.description,
 777→        tool_use_id: msg.request.tool_use_id,
 778→        agent_id: msg.request.agent_id,
 779→        timestamp: Date.now(),
 780→      };
 781→      session.pendingPermissions.set(msg.request_id, perm);
 782→
 783→      this.broadcastToBrowsers(session, {
 784→        type: "permission_request",
 785→        request: perm,
 786→      });
 787→      this.persistSession(session);
 788→    }
 789→  }
 790→
 791→  private handleToolProgress(session: Session, msg: CLIToolProgressMessage) {
 792→    this.broadcastToBrowsers(session, {
 793→      type: "tool_progress",
 794→      tool_use_id: msg.tool_use_id,
 795→      tool_name: msg.tool_name,
 796→      elapsed_time_seconds: msg.elapsed_time_seconds,
 797→    });
 798→  }
 799→
 800→  private handleToolUseSummary(session: Session, msg: CLIToolUseSummaryMessage) {
 801→    this.broadcastToBrowsers(session, {
 802→      type: "tool_use_summary",
 803→      summary: msg.summary,
 804→      tool_use_ids: msg.preceding_tool_use_ids,
 805→    });
 806→  }
 807→
 808→  private handleAuthStatus(session: Session, msg: CLIAuthStatusMessage) {
 809→    this.broadcastToBrowsers(session, {
 810→      type: "auth_status",
 811→      isAuthenticating: msg.isAuthenticating,
 812→      output: msg.output,
 813→      error: msg.error,
 814→    });
 815→  }
 816→
 817→  // ── Browser message routing ─────────────────────────────────────────────
 818→
 819→  private routeBrowserMessage(session: Session, msg: BrowserOutgoingMessage) {
 820→    // For Codex sessions, delegate entirely to the adapter
 821→    if (session.backendType === "codex") {
 822→      // Store user messages in history for replay with stable ID for dedup on reconnect
 823→      if (msg.type === "user_message") {
 824→        const ts = Date.now();
 825→        session.messageHistory.push({
 826→          type: "user_message",
 827→          content: msg.content,
 828→          timestamp: ts,
 829→          id: `user-${ts}-${this.userMsgCounter++}`,
 830→        });
 831→        this.persistSession(session);
 832→      }
 833→      if (msg.type === "permission_response") {
 834→        session.pendingPermissions.delete(msg.request_id);
 835→        this.persistSession(session);
 836→      }
 837→
 838→      if (session.codexAdapter) {
 839→        session.codexAdapter.sendBrowserMessage(msg);
 840→      } else {
 841→        // Adapter not yet attached — queue for when it's ready.
 842→        // The adapter itself also queues during init, but this covers
 843→        // the window between session creation and adapter attachment.
 844→        console.log(`[ws-bridge] Codex adapter not yet attached for session ${session.id}, queuing ${msg.type}`);
 845→        session.pendingMessages.push(JSON.stringify(msg));
 846→      }
 847→      return;
 848→    }
 849→
 850→    // Claude Code path (existing logic)
 851→    switch (msg.type) {
 852→      case "user_message":
 853→        this.handleUserMessage(session, msg);
 854→        break;
 855→
 856→      case "permission_response":
 857→        this.handlePermissionResponse(session, msg);
 858→        break;
 859→
 860→      case "interrupt":
 861→        this.handleInterrupt(session);
 862→        break;
 863→
 864→      case "set_model":
 865→        this.handleSetModel(session, msg.model);
 866→        break;
 867→
 868→      case "set_permission_mode":
 869→        this.handleSetPermissionMode(session, msg.mode);
 870→        break;
 871→    }
 872→  }
 873→
 874→  private handleUserMessage(
 875→    session: Session,
 876→    msg: { type: "user_message"; content: string; session_id?: string; images?: { media_type: string; data: string }[] }
 877→  ) {
 878→    // Store user message in history for replay with stable ID for dedup on reconnect
 879→    const ts = Date.now();
 880→    session.messageHistory.push({
 881→      type: "user_message",
 882→      content: msg.content,
 883→      timestamp: ts,
 884→      id: `user-${ts}-${this.userMsgCounter++}`,
 885→    });
 886→
 887→    // Build content: if images are present, use content block array; otherwise plain string
 888→    let content: string | unknown[];
 889→    if (msg.images?.length) {
 890→      const blocks: unknown[] = [];
 891→      for (const img of msg.images) {
 892→        blocks.push({
 893→          type: "image",
 894→          source: { type: "base64", media_type: img.media_type, data: img.data },
 895→        });
 896→      }
 897→      blocks.push({ type: "text", text: msg.content });
 898→      content = blocks;
 899→    } else {
 900→      content = msg.content;
 901→    }
 902→
 903→    const ndjson = JSON.stringify({
 904→      type: "user",
 905→      message: { role: "user", content },
 906→      parent_tool_use_id: null,
 907→      session_id: msg.session_id || session.state.session_id || "",
 908→    });
 909→    this.sendToCLI(session, ndjson);
 910→    this.persistSession(session);
 911→  }
 912→
 913→  private handlePermissionResponse(
 914→    session: Session,
 915→    msg: { type: "permission_response"; request_id: string; behavior: "allow" | "deny"; updated_input?: Record<string, unknown>; updated_permissions?: unknown[]; message?: string }
 916→  ) {
 917→    // Remove from pending
 918→    const pending = session.pendingPermissions.get(msg.request_id);
 919→    session.pendingPermissions.delete(msg.request_id);
 920→
 921→    if (msg.behavior === "allow") {
 922→      const response: Record<string, unknown> = {
 923→        behavior: "allow",
 924→        updatedInput: msg.updated_input ?? pending?.input ?? {},
 925→      };
 926→      if (msg.updated_permissions?.length) {
 927→        response.updatedPermissions = msg.updated_permissions;
 928→      }
 929→      const ndjson = JSON.stringify({
 930→        type: "control_response",
 931→        response: {
 932→          subtype: "success",
 933→          request_id: msg.request_id,
 934→          response,
 935→        },
 936→      });
 937→      this.sendToCLI(session, ndjson);
 938→    } else {
 939→      const ndjson = JSON.stringify({
 940→        type: "control_response",
 941→        response: {
 942→          subtype: "success",
 943→          request_id: msg.request_id,
 944→          response: {
 945→            behavior: "deny",
 946→            message: msg.message || "Denied by user",
 947→          },
 948→        },
 949→      });
 950→      this.sendToCLI(session, ndjson);
 951→    }
 952→  }
 953→
 954→  private handleInterrupt(session: Session) {
 955→    const ndjson = JSON.stringify({
 956→      type: "control_request",
 957→      request_id: randomUUID(),
 958→      request: { subtype: "interrupt" },
 959→    });
 960→    this.sendToCLI(session, ndjson);
