 962→
 963→  private handleSetModel(session: Session, model: string) {
 964→    const ndjson = JSON.stringify({
 965→      type: "control_request",
 966→      request_id: randomUUID(),
 967→      request: { subtype: "set_model", model },
 968→    });
 969→    this.sendToCLI(session, ndjson);
